def make_variable_lattice(cell_sizes_r, cell_sizes_c, seeds):
    h=sum(cell_sizes_r)+len(cell_sizes_r)-1; w=sum(cell_sizes_c)+len(cell_sizes_c)-1
    g=[[0]*w for _ in range(h)]
    rstarts=[]; pos=0
    for size in cell_sizes_r:
        rstarts.append(pos); pos+=size+1
    cstarts=[]; pos=0
    for size in cell_sizes_c:
        cstarts.append(pos); pos+=size+1
    for r in rstarts[1:]: g[r-1]=[8]*w
    for c in cstarts[1:]:
        for r in range(h): g[r][c-1]=8
    for ri,cj,color,dr,dc in seeds:
        g[rstarts[ri]+dr][cstarts[cj]+dc]=color
    return g

def expected_from_cells(row_sizes,col_sizes,cells):
    g=make_variable_lattice(row_sizes,col_sizes,[])
    rs=[]; p0=0
    for size in row_sizes: rs.append(list(range(p0,p0+size)));p0+=size+1
    cs=[]; p0=0
    for size in col_sizes: cs.append(list(range(p0,p0+size)));p0+=size+1
    for i,rr in enumerate(rs):
        for j,cc in enumerate(cs):
            for r in rr:
                for c in cc:g[r][c]=cells[i][j]
    return g

